def label_items(items):
    lines = []
    for item in items:
        lines.append(f"Packed: {item}")
    return lines

def long_names(names):
    result = []
    for name in names:
        if len(name) >= 5:
            result.append(name)
    return result

def party_summary(party, supplies):
    return {
        "member_count": len(party),
        "supply_count": len(supplies),
    }

def build_dispatch(destination, party, supplies, status="Review"):
    return {
        "destination": destination,
        "member_count": len(party),
        "supply_count": len(supplies),
        "status": status,
    }
